CREATE SCHEMA IF NOT EXISTS observatory;
SET search_path TO observatory, public;
CREATE TABLE projects (id text PRIMARY KEY, name text NOT NULL, repo text NOT NULL, scope text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tasks (id text PRIMARY KEY, project_id text REFERENCES projects(id), title text NOT NULL, goal text NOT NULL DEFAULT '', acceptance text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'active', outcome text, source jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX tasks_project_updated ON tasks(project_id, updated_at DESC, id);
CREATE TABLE turns (turn_key text PRIMARY KEY, session_id text NOT NULL, turn_id text NOT NULL, workspace text NOT NULL DEFAULT '', prompt text NOT NULL DEFAULT '', started_at timestamptz, finished_at timestamptz, completed boolean NOT NULL DEFAULT false, role text, agent_type text, source jsonb NOT NULL DEFAULT '{}', UNIQUE(session_id,turn_id));
CREATE INDEX turns_workspace_started ON turns(workspace,started_at DESC,turn_key);
CREATE TABLE assignments (turn_key text PRIMARY KEY REFERENCES turns(turn_key), task_id text NOT NULL REFERENCES tasks(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX assignments_task ON assignments(task_id,turn_key);
CREATE TABLE settings (key text PRIMARY KEY, value jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE categorization_rules (id text PRIMARY KEY, name text NOT NULL, pattern text NOT NULL, category text NOT NULL, activity_type text NOT NULL DEFAULT 'uncategorized', priority integer NOT NULL DEFAULT 100, enabled boolean NOT NULL DEFAULT true, source jsonb NOT NULL DEFAULT '{}');
CREATE TABLE steering_rules (id text PRIMARY KEY, name text NOT NULL, kind text NOT NULL, mode text NOT NULL CHECK(mode IN ('log','warn','ask','block')), enabled boolean NOT NULL DEFAULT true, builtin boolean NOT NULL DEFAULT false, config jsonb NOT NULL DEFAULT '{}', message text NOT NULL DEFAULT '');
CREATE TABLE live_sessions (id text PRIMARY KEY, workspace text NOT NULL DEFAULT '', last_seen timestamptz NOT NULL, status text NOT NULL DEFAULT 'working', paused boolean NOT NULL DEFAULT false, task_id text, task_cost double precision, context_tokens bigint, state jsonb NOT NULL DEFAULT '{}');
CREATE INDEX live_sessions_seen ON live_sessions(last_seen DESC);
CREATE TABLE steering_events (id text PRIMARY KEY, session_id text NOT NULL, payload_hash text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE steering_state (session_id text NOT NULL, rule_id text NOT NULL, value jsonb NOT NULL, PRIMARY KEY(session_id,rule_id));
CREATE TABLE steering_notes (id text PRIMARY KEY, session_id text NOT NULL REFERENCES live_sessions(id), message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz);
CREATE INDEX pending_notes ON steering_notes(session_id,created_at) WHERE delivered_at IS NULL;
CREATE TABLE steering_log (id text PRIMARY KEY, session_id text NOT NULL, at timestamptz NOT NULL DEFAULT now(), rule_id text, rule_name text NOT NULL, mode text NOT NULL, message text NOT NULL, call text NOT NULL DEFAULT '', workspace text NOT NULL DEFAULT '', event_id text);
CREATE INDEX steering_log_at ON steering_log(at DESC,id);
CREATE TABLE analysis_batches (id text PRIMARY KEY, status text NOT NULL DEFAULT 'queued', corpus_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, source jsonb NOT NULL DEFAULT '{}');
CREATE TABLE analysis_jobs (id text PRIMARY KEY, task_id text REFERENCES tasks(id), batch_id text REFERENCES analysis_batches(id), operation text NOT NULL, status text NOT NULL DEFAULT 'queued', model text NOT NULL, snapshot_hash text NOT NULL, snapshot jsonb NOT NULL, result jsonb, usage jsonb, error text, source jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, finished_at timestamptz);
CREATE UNIQUE INDEX one_active_task_analysis ON analysis_jobs(task_id) WHERE status IN ('queued','running');
CREATE INDEX queued_analysis_jobs ON analysis_jobs(created_at,id) WHERE status='queued';
CREATE TABLE analyses (id text PRIMARY KEY, task_id text REFERENCES tasks(id), job_id text REFERENCES analysis_jobs(id), snapshot_hash text NOT NULL, summary text NOT NULL, task_type text NOT NULL DEFAULT 'unclassified', result jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX analyses_current ON analyses(task_id,created_at DESC,id);
CREATE TABLE subtasks (id text PRIMARY KEY, analysis_id text NOT NULL REFERENCES analyses(id), position integer NOT NULL, title text NOT NULL, summary text NOT NULL DEFAULT '', category text NOT NULL, confidence double precision, event_ids text[] NOT NULL, result jsonb NOT NULL DEFAULT '{}', UNIQUE(analysis_id,position));
CREATE INDEX subtasks_events ON subtasks USING gin(event_ids);
CREATE TABLE evidence_notes (id text PRIMARY KEY, task_id text REFERENCES tasks(id), kind text NOT NULL, title text NOT NULL, detail text NOT NULL DEFAULT '', reference text NOT NULL DEFAULT '', outcome text NOT NULL DEFAULT 'unknown', created_at timestamptz NOT NULL DEFAULT now(), source jsonb NOT NULL DEFAULT '{}');
CREATE TABLE retained_images (id text PRIMARY KEY, task_id text REFERENCES tasks(id), event_id text NOT NULL, mime text NOT NULL CHECK(mime IN ('image/png','image/jpeg','image/webp')), bytes bytea NOT NULL CHECK(octet_length(bytes)<=1048576));
CREATE TABLE applied_changes (id text PRIMARY KEY, title text NOT NULL, applied_at timestamptz NOT NULL, workspace text NOT NULL DEFAULT '', takes_effect text NOT NULL DEFAULT 'immediate' CHECK(takes_effect IN ('immediate','new_sessions')), metrics text[] NOT NULL, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE source_files (path text PRIMARY KEY, bytes bigint NOT NULL, mtime_ms bigint NOT NULL, sha256 text, error text, imported_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE event_versions (id text PRIMARY KEY, version bigint GENERATED ALWAYS AS IDENTITY, payload_hash text NOT NULL, usage_hash text, event_time text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE event_outbox (event_id text PRIMARY KEY REFERENCES event_versions(id), version bigint NOT NULL, payload jsonb NOT NULL, delivered_at timestamptz);
CREATE INDEX pending_event_outbox ON event_outbox(version) WHERE delivered_at IS NULL;
CREATE TABLE ingest_conflicts (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, event_id text NOT NULL, source_hash text NOT NULL, reason text NOT NULL, at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, at timestamptz NOT NULL DEFAULT now(), action text NOT NULL, entity text NOT NULL, details jsonb NOT NULL DEFAULT '{}');
CREATE TABLE migration_manifests (id text PRIMARY KEY, source text NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, manifest jsonb NOT NULL DEFAULT '{}');
CREATE TABLE archived_records (import_id text NOT NULL REFERENCES migration_manifests(id), table_name text NOT NULL, row_number bigint NOT NULL, record jsonb NOT NULL, PRIMARY KEY(import_id,table_name,row_number));
INSERT INTO settings(key,value) VALUES ('pricing','{"unit":"USD","models":{}}'),('collection_enabled','false') ON CONFLICT DO NOTHING;
